// ─────────────────────────────────────────────────────────────────────────
//  01 · compose order filters★★☆
//  concepts: Predicate.and · lambdas · parsing
// ─────────────────────────────────────────────────────────────────────────

import static bootcamp.Check.*;

import java.util.*;
import java.util.function.*;

class Exercise {

    record Order(String customer, String status, long totalCents) {}

    /** One composed predicate for a comma-separated key:value filter spec. */
    static Predicate<Order> parseFilter(String spec) {
        Predicate<Order> p = o -> true;
        if (spec == null || spec.isBlank()) return p;
        for (var term : spec.split(",")) {
            var kv = term.strip().split(":", 2);
            if (kv.length != 2) throw new IllegalArgumentException("bad term " + term);
            var value = kv[1].strip();
            p = p.and(switch (kv[0].strip().toLowerCase(Locale.ROOT)) {
                case "status" -> o -> o.status().equalsIgnoreCase(value);
                case "min" -> {
                    long min = parseMin(value);
                    yield o -> o.totalCents() >= min;
                }
                case "customer" -> o -> o.customer().toLowerCase(Locale.ROOT).contains(value.toLowerCase(Locale.ROOT));
                default -> throw new IllegalArgumentException("unknown filter " + kv[0]);
            });
        }
        return p;
    }

    static long parseMin(String value) {
        try {
            return Long.parseLong(value);
        } catch (NumberFormatException e) {
            throw new IllegalArgumentException("min must be a number: " + value, e);
        }
    }

    // ─── tests ───────────────────────────────────────────────────────────
    public static void main(String[] args) {
        test("status and min combine with AND", () -> { var f = parseFilter("status:paid,min:1000"); ok(f.test(new Order("ana", "paid", 1500)) && !f.test(new Order("ana", "paid", 999)) && !f.test(new Order("ana", "open", 5000)), "status and min"); });
        test("customer matches a case-insensitive substring", () -> { var f = parseFilter("customer:ANA"); ok(f.test(new Order("Ana Lima", "open", 1)) && !f.test(new Order("Bo", "open", 1)), "customer"); });
        test("status matching ignores case and spaces", () -> ok(parseFilter(" status : PAID ").test(new Order("x", "paid", 1)), "case and spaces"));
        test("a blank spec accepts everything (boundary)", () -> ok(parseFilter("").test(new Order("x", "any", 0)) && parseFilter(null).test(new Order("y", "z", 1)), "accept all"));
        test("bad specs fail while parsing", () -> { raises(IllegalArgumentException.class, () -> parseFilter("color:red")); raises(IllegalArgumentException.class, () -> parseFilter("min:lots")); raises(IllegalArgumentException.class, () -> parseFilter("paid")); });
        System.exit(report());
    }
    // ─── end tests ───────────────────────────────────────────────────────
}

drills.explanation:
Start from an always-true predicate and AND one small predicate per term:

```java
Predicate<Order> p = o -> true;
for (var term : spec.split(",")) {
    var kv = term.strip().split(":", 2);
    if (kv.length != 2) throw new IllegalArgumentException("bad term " + term);
    var value = kv[1].strip();
    p = p.and(switch (kv[0].strip().toLowerCase(Locale.ROOT)) {
        case "status" -> o -> o.status().equalsIgnoreCase(value);
        case "min" -> { long min = parseMin(value); yield o -> o.totalCents() >= min; }
        case "customer" -> o -> o.customer().toLowerCase(Locale.ROOT).contains(value.toLowerCase(Locale.ROOT));
        default -> throw new IllegalArgumentException("unknown filter " + kv[0]);
    });
}
```

Parsing `min` once, outside the lambda, means a bad number fails while parsing, and the predicate does no string work per order. Each lambda captures `value` and `min`, which are effectively final.

